import{_t as e,it as t,n,rt as r}from"./chunks/framework.CEeTaPkX.js";var i=JSON.parse(`{"title":"Pi Durable harness","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/harness.md","filePath":"architecture/harness.md","lastUpdated":1792141151000}`),a={name:`architecture/harness.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="pi-durable-harness" tabindex="-1">Pi Durable harness <a class="header-anchor" href="#pi-durable-harness" aria-label="Permalink to “Pi Durable harness”">​</a></h1><p>Caret depends on <strong><code>@earendil-works/pi-durable</code></strong> and <strong><code>@earendil-works/pi-ai</code></strong>, with <strong><code>@earendil-works/chord</code></strong> providing execution context. The repository manifest declares <code>^1.0.2</code> for all three; the baseline lockfile resolves all three to <code>1.0.2</code>. “Pi Durable” is the package&#39;s real name, not a generic label for Caret&#39;s task runner.</p><h2 id="what-the-harness-abstracts" tabindex="-1">What the harness abstracts <a class="header-anchor" href="#what-the-harness-abstracts" aria-label="Permalink to “What the harness abstracts”">​</a></h2><table tabindex="0"><thead><tr><th>Abstraction used here</th><th>Role in Caret</th><th>Caret&#39;s addition</th></tr></thead><tbody><tr><td><code>Harness</code> and SQLite storage</td><td>Open durable agent storage and manage conversations</td><td><code>openAgent</code> wires providers, registry, environment and retry settings</td></tr><tr><td>Conversation</td><td>Submit input, wait, abort, configure model, read context</td><td>One v2 conversation per bounded Mac task</td></tr><tr><td><code>defineExtension</code> / registry</td><td>Install named tools, sections and hooks</td><td><code>mac-control</code>, tracing and legacy shadow approvals</td></tr><tr><td><code>defineTool</code></td><td>Declare parameters, execution and replay behavior</td><td><code>observe</code>, journaled <code>act</code>, and <code>finish</code></td></tr><tr><td><code>defineDoc</code> / transactions</td><td>Store typed domain documents</td><td><code>caret.task</code> and trace-to-task index</td></tr><tr><td><code>section</code></td><td>Render prompt content from code on requests</td><td>Current computer-use instructions reach existing conversations</td></tr><tr><td><code>GenerationTask</code> hooks</td><td>Transform model requests and react to responses/yields</td><td>Trim old observations, mask secret context, limit extra acts and nudge completion</td></tr><tr><td><code>NodeExecutionEnv</code></td><td>Supply a Node execution environment and cwd</td><td>Constructed from the conversation&#39;s requested cwd or process cwd</td></tr></tbody></table><p>These are the APIs Caret actually imports and calls. This page does not claim to describe every facility in the upstream library.</p><h2 id="opening-the-engine" tabindex="-1">Opening the engine <a class="header-anchor" href="#opening-the-engine" aria-label="Permalink to “Opening the engine”">​</a></h2><p><code>openAgent</code> creates the model registry, registers Baseten and optionally OpenRouter, installs the selected <code>mac-control</code> implementation and tracing, then opens <code>agent.sqlite</code> with <code>openNodeSqliteStorage</code>. It creates the long-lived root conversation and a Caret task runner over the same harness.</p><p>Provider retry settings are eight retries with a 2-second initial backoff. The primary Pi model defaults to <code>zai-org/GLM-5.3-Fast</code>; fallback configuration is enabled only when <code>OPENROUTER_API_KEY</code> exists. Configuring a fallback model is distinct from invoking a failover in a running task.</p><p>The returned <code>ask</code> and <code>runTask</code> entry points share a promise queue so trace attribution stays unambiguous. The async server/supervisor adapter also uses task-runner operations directly; this queue is not a claim that every possible task start across all adapters is globally serialized.</p><h2 id="task-lifecycle" tabindex="-1">Task lifecycle <a class="header-anchor" href="#task-lifecycle" aria-label="Permalink to “Task lifecycle”">​</a></h2><div class="language-text line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>start(TaskSpec)</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ├── resume.trace_id ─── find existing conversation, clear result,</span></span>
<span class="line"><span>   │                      retain history, submit user&#39;s answer</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   └── new trace ───────── create conversation + caret.task + index</span></span>
<span class="line"><span>                              │</span></span>
<span class="line"><span>                              ▼</span></span>
<span class="line"><span>                     submit task card (stable requestId)</span></span>
<span class="line"><span>                              │</span></span>
<span class="line"><span>                     observe → act → inspect result</span></span>
<span class="line"><span>                              │              ▲</span></span>
<span class="line"><span>                              └──────────────┘</span></span>
<span class="line"><span>                              │</span></span>
<span class="line"><span>                            finish</span></span>
<span class="line"><span>                              │</span></span>
<span class="line"><span>                         waitForIdle</span></span>
<span class="line"><span>                              │</span></span>
<span class="line"><span>                task record / usage / secret cleanup</span></span>
<span class="line"><span>                              │</span></span>
<span class="line"><span>                          TaskResult</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br></div></div><p><code>TaskRunner.start</code> returns <code>task_id</code>, <code>trace_id</code> and whether this was an explicit resume. <code>progress</code> derives a snapshot from the task document and includes live model retry state when available. <code>wait</code> waits for idle and builds the result. <code>run</code> is <code>start</code> followed by <code>wait</code>.</p><p>An unfinished trace can reuse its conversation. Repeating an already-finished trace allocates the next suffix (<code>~2</code>, <code>~3</code>, …), so a later attempt does not simply return the old result. Explicit <code>resume</code> after a user question preserves the conversation and submits a new answer with a resume-specific request ID.</p><p>Phases (<code>queued</code>, <code>running</code>, <code>finished</code>) describe lifecycle; statuses describe outcomes. The model-facing <code>finish</code> accepts <code>success</code>, <code>partial</code>, <code>failed</code>, and <code>needs_user</code>. Executor and runner paths also produce <code>blocked_safety</code>, <code>budget_exhausted</code>, and <code>interrupted</code>.</p><h2 id="completion-has-evidence-rules" tabindex="-1">Completion has evidence rules <a class="header-anchor" href="#completion-has-evidence-rules" aria-label="Permalink to “Completion has evidence rules”">​</a></h2><p>A requested <code>success</code> rechecks <code>TaskSpec.success_checks</code>. If checks fail, the first completion attempt is rejected so the model can repair the result. A repeated failed claim is downgraded to <code>partial</code>. Without explicit success checks, a failed last-batch <code>expect</code> can reject success. A visual predicate attaches a screenshot for model judgment; it is not a deterministic visual verifier.</p><p>The generation hook nudges an unfinished model to call <code>finish</code>. If it still ends in plain text, <code>wait</code> settles the task as <code>partial</code>; an error or aborted assistant response becomes <code>interrupted</code>. A fluent answer is not automatically a successful task.</p><h2 id="durability-and-replay-boundaries" tabindex="-1">Durability and replay boundaries <a class="header-anchor" href="#durability-and-replay-boundaries" aria-label="Permalink to “Durability and replay boundaries”">​</a></h2><p><code>observe</code> is marked replay-safe because it reads the UI. <code>act</code> is replay-safe <strong>because Caret implements its own per-action journal</strong>, not because typing is inherently safe to repeat. It runs sequentially and memoizes action state using the tool-call ID as batch identity. See <a href="./execution.html">execution</a> for the interruption boundary.</p><p>On startup Caret aborts unfinished work and attempts secret cleanup unless <code>CARET_RESUME_ON_START=1</code>. Only then does it call <code>harness.resume()</code>. Persistence enables recovery; the default product behavior deliberately cancels foreground work after a restart.</p><p><code>extraActs</code>, completion nudges and the draft ledger are process-local state. They should not be mistaken for durable documents. Native UI state can also change while the agent is stopped, so old observations must be checked again.</p><h2 id="source-trail" tabindex="-1">Source trail <a class="header-anchor" href="#source-trail" aria-label="Permalink to “Source trail”">​</a></h2><p><a href="https://github.com/krishpop/caret/blob/57d53c0/package.json" target="_blank" rel="noreferrer">Dependency manifest</a> · <a href="https://github.com/krishpop/caret/blob/57d53c0/package-lock.json" target="_blank" rel="noreferrer">Lockfile</a> · <a href="https://github.com/krishpop/caret/blob/57d53c0/src/harness.ts" target="_blank" rel="noreferrer">Harness wiring</a> · <a href="https://github.com/krishpop/caret/blob/57d53c0/src/cu/task.ts" target="_blank" rel="noreferrer">Task runner</a> · <a href="https://github.com/krishpop/caret/blob/57d53c0/src/cu/state.ts" target="_blank" rel="noreferrer">Documents</a> · <a href="https://github.com/krishpop/caret/blob/57d53c0/src/cu/tools.ts" target="_blank" rel="noreferrer">Tools and hooks</a></p>`,23)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};